use std::collections::HashMap;impl Solution{pub fn max_points(p:Vec<Vec<i32>>)->i32{fn g(mut a:i32,mut b:i32)->i32{a=a.abs();b=b.abs();while b!=0{let t=a%b;a=b;b=t;}a}let mut best=0;for i in 0..p.len(){let mut m:HashMap<(i32,i32),i32>=HashMap::new();let(mut dup,mut local)=(1,0);for j in i+1..p.len(){let(mut dx,mut dy)=(p[j][0]-p[i][0],p[j][1]-p[i][1]);if dx==0&&dy==0{dup+=1;continue}let z=g(dx,dy);dx/=z;dy/=z;if dx<0||(dx==0&&dy<0){dx=-dx;dy=-dy}let c=m.entry((dx,dy)).or_insert(0);*c+=1;local=local.max(*c);}best=best.max(local+dup);}best}}
